// Parent class with independent width/height
class Rectangle {
    protected int width;
    protected int height;

    public void setWidth(int width) { this.width = width; }
    public void setHeight(int height) { this.height = height; }
    public int getArea() { return width * height; }
}

// Square enforces width == height, violating LSP
class Square extends Rectangle {
    @Override
    public void setWidth(int width) {
        this.width = width;
        this.height = width;  // Caller doesn't expect this side effect
    }
    @Override
    public void setHeight(int height) {
        this.width = height;  // Breaks Rectangle contract
        this.height = height;
    }
}

// This method works for Rectangle but fails for Square
void testRectangle(Rectangle rect) {
    rect.setWidth(5);
    rect.setHeight(4);
    assert rect.getArea() == 20;  // Fails for Square: returns 16
}

// Common interface with no shared mutable state
interface Shape {
    int getArea();
    int getPerimeter();
}

// Rectangle and Square are independent implementations
record Rectangle(int width, int height) implements Shape {
    @Override
    public int getArea() { return width * height; }

    @Override
    public int getPerimeter() { return 2 * (width + height); }
}

record Square(int side) implements Shape {
    @Override
    public int getArea() { return side * side; }

    @Override
    public int getPerimeter() { return 4 * side; }
}

// Now clients depend on Shape interface
void processShape(Shape shape) {
    var area = shape.getArea();  // Works for both, no surprises
    System.out.println("Area: " + area);
}

import java.util.*;

// Client code expects List behavior
void addItemsToList(List<String> list) {
    list.add("item1");  // Caller expects this to work
    list.add("item2");
}

// Usage that works fine
void normalUsage() {
    var normalList = new ArrayList<String>();
    addItemsToList(normalList);  // No problem
}

// LSP violation at runtime
void problematicUsage() {
    var readOnlyList = Collections.unmodifiableList(new ArrayList<String>());
    addItemsToList(readOnlyList);  // Throws UnsupportedOperationException
}

// Custom example: improper inheritance
class ReadOnlyRepository extends UserRepository {
    @Override
    public void save(User user) {
        throw new UnsupportedOperationException("Read-only");  // LSP violation
    }
}

interface PaymentService {
    // Contract: returns transaction ID, throws PaymentException on failure
    // Postcondition: order status is updated to PAID or FAILED
    String processPayment(Long orderId, BigDecimal amount);
}

@Service
class StripePaymentService implements PaymentService {
    @Override
    public String processPayment(Long orderId, BigDecimal amount) {
        var transactionId = stripeApi.charge(amount);  // Call Stripe
        orderRepo.updateStatus(orderId, OrderStatus.PAID);  // Honors contract
        return transactionId;
    }
}

// Contract violation: returns null, doesn't update order
@Service
class MockPaymentService implements PaymentService {
    @Override
    public String processPayment(Long orderId, BigDecimal amount) {
        return null;  // Violates postcondition: must return transaction ID
        // Missing: order status update
    }
}

